from pathlib import Path
import json
r=Path(__file__).resolve().parent;v=json.loads((r/'validation.json').read_text());a=json.loads((r/'analysis.json').read_text());assert len(a['records'])==18
monitors=[json.loads(p.read_text()) for p in (r/'timings').glob('*.monitor.json')]
assert len(monitors)==18 and all(x['exitCode']==0 and not x['unexpectedActivity'] and x['foreignCPUThresholdCores']==.10 for x in monitors)
summary='Rejected. BMW off (+0.628277%/-0.580383%),2x (+0.233556%/-0.037711%) and4x (-0.979528%/+0.708239%) show opposite audit directions; faster/slower pairs are4/2,2/4 and3/3. There is no reproducible primary-scene benefit. T-80 controls are also mixed; its2x second-audit benefit (-1.763500%) does not repeat in the first (+0.126377%). All correctness gates pass and all eighteen quiet comparisons pass on their first attempt. Keep the accepted D4 renderer/live preview unchanged. This is a failure to demonstrate benefit, not proof that packing locality or architecture cannot improve further.'
d=dict(status='rejected',summary=summary,referenceWasmSha256=v['referenceWasmSha256'],candidateWasmSha256=v['candidateWasmSha256'],fullCorrectnessGatesPassed=True,all18ComparisonsCompleted=True,quietGuardAttempts=18,quietGuardFirstAttemptsPassed=18,sourceAndLiveUnchanged=True,decisionRule=v['decisionRule'],pairDispersion='Retain every pair. No uniform regression, statistical certainty, hardware/cache cause or ceiling inferred; no selective exclusion/reconfirmation or parameter sweep.',limitations='This trial combines early sampler/layout work, allocation/idle reclamation,128-item local chunks, worker packing and ownership swaps. Timings do not isolate these or measure how many BMW draws actually acquired early storage. D4 packing counters are not candidate uptake.',nextResearchDirection='Measure candidate early-packing uptake and caller/worker stage costs before selecting a direct packed-vertex producer design. Identify budget misses and raster displacement; keep those observations separate from noninstrumented timing claims.')
(r/'decision.json').write_text(json.dumps(d,indent=2)+'\n');v.update(status='rejected-after-full-correctness-and-all18-quiet-comparisons',comparisonCount=18,decision=summary)
(r/'validation.json').write_text(json.dumps(v,indent=2)+'\n')
